import { OrderRepository } from '../repositories/order-repository.js';

const orders = new OrderRepository();

export function listOrdersForUser(userId) {
  return orders.findByUser(userId);
}

export async function totalPaidCents() {
  const rows = await orders.findPaid();
  return rows.reduce((sum, o) => sum + o.total_cents, 0);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', async () => {
  const orders = await listOrdersForUser(1);
  assert.equal(orders.length, 2);
  assert.ok(orders.every((o) => o.user_id === 1));
});

test('totalPaidCents counts only paid orders', async () => {
  const total = await totalPaidCents();
  assert.equal(total, 4200 + 9900 + 500);
});

